insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25634')::uuid, md5('building-willy-brandt-strasse-57-20457')::uuid, '25634', 'moderne-bueroflaeche-direkt-am-nikolaifleet-25634', 'Moderne Bürofläche direkt am Nikolaifleet', 'Der imposante Bürokomplex befindet sich in äußerst verkehrsgünstiger Lage unmittelbar am Nikolaifleet an der wichtigsten Ost-West-Verbindung südlich des Hamburger Innenstadtkerns. …', 'Der imposante Bürokomplex befindet sich in äußerst verkehrsgünstiger Lage unmittelbar am Nikolaifleet an der wichtigsten Ost-West-Verbindung südlich des Hamburger Innenstadtkerns. Die U-Bahnstation Meßberg ist fußläufig schnell erreicht und sichert den Anschluss an den öffentlichen Nahverkehr. Gute Einkaufsmöglichkeiten und diverse Cafés und Restaurants prägen das nahe Umfeld. Die moderne ausgestattete Bürofläche erschließt sich über zwei Personenaufzüge im Objekt. Die weitere Ausstattung und Aufteilung erfolgt in Absprache mit dem zukünftigen Mieter. Diese Innenbilder sind beispielhaft gewählt und stammen aus einer ähnlichen Fläche im Objekt. PKW-Stellplätze stehen in der  hauseigenen Tiefgarage zur Anmietung bereit.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze', 'wasserblick']::text[], 259, 544, 'https://www.buerohamburg.de/objects/pdf/BHI_25634.pdf', null, 'filemaker', '25634') on conflict (id) do nothing;
