insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24401')::uuid, md5('building-millerntorplatz-1-20359')::uuid, '24401', 'st-pauli-modernes-buero-am-millerntor-24401', 'St. Pauli: Modernes Büro am Millerntor', 'Der imposante Gebäudekomplex befindet sich zwischen der City und St. Pauli in prominenter Nachbarschaft zum Dom und den Tanzenden Türmen. Das lebendige Umfeld ist geprägt durch …', 'Der imposante Gebäudekomplex befindet sich zwischen der City und St. Pauli in prominenter Nachbarschaft zum Dom und den Tanzenden Türmen. Das lebendige Umfeld ist geprägt durch zahlreiche Cafés und Restaurants sowie diverse Geschäfte des täglichen Bedarfs. Die Anbindung an den ÖPNV ist durch die nur wenige Meter entfernte U-Bahnstation St. Pauli sowie diverse umliegende Bushaltestellen als sehr gut zu bezeichnen. Das Haus bietet eine interessante Architektur mit einem innen liegenden Lichthof, einem repräsentativen Eingangsbereich mit Empfangsservice und zahlreichen Personenaufzügen. Zur aktuellen Ausstattung der hellen Bürofläche zählen Teppichfußboden, fast bodentiefe Fenster, innen liegender Sonnenschutz, teilweise Glastrennwände, Beleuchtungssysteme, getrennte WC-Bereiche und eine Pantry. Die Innenansichten stammen aus einer renovierten Fläche im Gebäude. Pkw-Stellplätze können in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['barrierefrei', 'stellplaetze']::text[], 474, 2047, 'https://www.buerohamburg.de/objects/pdf/BHI_24401.pdf', null, 'filemaker', '24401') on conflict (id) do nothing;
insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-24401-1')::uuid, md5('property-24401')::uuid, 'Mietfläche', 547, 19, null, 'filemaker', '24401-1') on conflict (id) do nothing;
