insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24376')::uuid, md5('building-essener-strasse-4-22419')::uuid, '24376', 'schoene-bueroflaeche-im-valvo-park-24376', 'Schöne Bürofläche im Valvo-Park', 'Das ehemalige Fabrikgebäude befindet sich auf dem Gelände des grünen und ruhigen Valvo-Parks am nördlichen Stadtrand von Hamburg, nur wenige Meter von der Langenhorner Chaussee …', 'Das ehemalige Fabrikgebäude befindet sich auf dem Gelände des grünen und ruhigen Valvo-Parks am nördlichen Stadtrand von Hamburg, nur wenige Meter von der Langenhorner Chaussee entfernt. Diverse Buslinien sichern den Anschluss an den ÖPNV. Auch der Autobahnanschluss ist schnell erreicht. Das Restaurant Marlin auf dem Gelände sorgt mit seinem preiswerten und abwechslungsreichen Mittagstisch für entspannte Pausen. Außerdem bietet die Fitnesskette Elixia auf ca. 4.300 qm ein umfassendes Sportangebot inklusive Swimmingpool. Die lichtdurchflutete Bürofläche verfügt aktuell über eine EDV-Verkabelung, eine Einbauküche sowie getrennte WC-Einheiten. Die weitere Aufteilung und Ausstattung erfolgt in Absprache mit dem zukünftigen Mieter. Diese Innenbilder sind beispielhaft gewählt. PKW-Stellplätze können auf dem Gelände angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['stellplaetze']::text[], 229, 1705, 'https://www.buerohamburg.de/objects/pdf/BHI_24376.pdf', null, 'filemaker', '24376') on conflict (id) do nothing;
