insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24405')::uuid, md5('building-sternstrasse-117-20357')::uuid, '24405', 'helle-bueroflaeche-im-herzen-der-schanze-ueber-drei-etagen-24405', 'Helle Bürofläche im Herzen der Schanze über drei Etagen', 'Das moderne Gewerbeobjekt befindet sich im pulsierenden Schanzenviertel – nur wenige Schritte von der U-Bahnstation Sternschanze entfernt. Die Lage überzeugt durch eine …', 'Das moderne Gewerbeobjekt befindet sich im pulsierenden Schanzenviertel – nur wenige Schritte von der U-Bahnstation Sternschanze entfernt. Die Lage überzeugt durch eine ausgezeichnete Infrastruktur mit sämtlichen Geschäften des täglichen Bedarfs sowie einer Vielzahl an Cafés, Bars und Restaurants. Auch die Hamburger Innenstadt ist in wenigen Minuten erreichbar.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-24405-1')::uuid, md5('property-24405')::uuid, 'Mietfläche', 550, 19.85, null, 'filemaker', '24405-1') on conflict (id) do nothing;
