insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-675')::uuid, md5('building-neumuehlen-15-22763')::uuid, '675', 'lichtdurchflutete-bueroflaeche-im-hanse-gate-am-elbufer-675', 'Lichtdurchflutete Bürofläche im Hanse-Gate am Elbufer', 'Das moderne Bürogebäude fasziniert neben seiner beeindruckenden Lage unmittelbar am Elbufer durch seine Transparenz und das sehr großzügige, farblich gestaltete Foyer. Der Bahnhof …', 'Das moderne Bürogebäude fasziniert neben seiner beeindruckenden Lage unmittelbar am Elbufer durch seine Transparenz und das sehr großzügige, farblich gestaltete Foyer. Der Bahnhof Altona mit all seinen Nah- und Fernverbindungen und seinen vielseitigen gastronomischen Angeboten ist fußläufig schnell erreicht. Eine Bushaltestelle befindet sich in unmittelbarer Nähe zum Objekt. Für eine abwechslungsreiche Mittagspause sorgen die zahlreichen Lokale in der Großen Elbstraße. Zur Ausstattung der Mietfläche zählt u.a. eine EDV-Verkabelung in Bodentanks, bodentiefe Fenster, Klimatisierung durch Betonkernaktivierung, eine Pantry sowie ein Teppichfußboden. Bei diesem Büro kann die Aufteilung der Mietfläche an die Bedürfnisse des Mieters angepasst werden. PKW-Stellplätze können in der hauseigenen Tiefgarage und im Außenbereich angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze', 'wasserblick']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_675.pdf', null, 'filemaker', '675') on conflict (id) do nothing;
