insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-8176')::uuid, md5('building-wendenstrasse-21a-c-20097')::uuid, '8176', 'attraktive-bueroflaeche-am-mittelkanal-in-der-citysued-8176', 'Attraktive Bürofläche am Mittelkanal in der CitySüd', 'Das moderne Büro- und Geschäftsgebäude befindet sich in verkehrsgünstiger Lage zwischen den Elbbrücken und der Hamburger Innenstadt. Im direkten Umfeld sind zahlreiche …', 'Das moderne Büro- und Geschäftsgebäude befindet sich in verkehrsgünstiger Lage zwischen den Elbbrücken und der Hamburger Innenstadt. Im direkten Umfeld sind zahlreiche gastronomische Angebote fußläufig schnell erreicht. Die nur wenige Meter entfernte U-Bahnstation Hammerbrook sichert eine gute Anbindung an das öffentliche Verkehrsnetz. Die Ausstattung umfasst u.a. einen Hohlraumboden für die EDV- und Strom- Verkabelung, außenliegenden Sonnenschutz, hochwertigen Bodenbelag, Pendelleuchten sowie eine eingerichtete Pantry. Die weitere Aufteilung und Ausstattung erfolgt in Absprache mit dem zukünftigen Mieter. Die Innenansichten stammen aus einer ähnlichen Fläche im Objekt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['wasserblick']::text[], 309, 995, 'https://www.buerohamburg.de/objects/pdf/BHI_8176.pdf', null, 'filemaker', '8176') on conflict (id) do nothing;
