insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25296')::uuid, md5('building-lademannbogen-21-23-22339')::uuid, '25296', 'ihr-neuer-firmensitz-nahe-des-flughafens-25296', 'Ihr neuer Firmensitz nahe des Flughafens', 'Der vielfältig nutzbare Gewerbekomplex, welcher Büro- und Archivflächen bereitstellt, befindet sich am Ring 3 nahe der A7 sowie des Flughafens. Die Anbindung an den ÖPNV ist durch …', 'Der vielfältig nutzbare Gewerbekomplex, welcher Büro- und Archivflächen bereitstellt, befindet sich am Ring 3 nahe der A7 sowie des Flughafens. Die Anbindung an den ÖPNV ist durch eine nahegelegene Bushaltestelle gegeben. Zur aktuellen Ausstattung der Büroflächen zählt ein Teppichboden, teilweise Laminatboden, eine Cat-7 Verkabelung, außenliegender Sonnenschutz, begrünte Innenhöfe , eine Pantry sowie separate WC-Einheiten. Die Flächen werden in Absprache mit dem zukünftigen Mieter neu aufgeteilt und ausgestattet. PKW-Stellplätze stehen am Objekt und in einer hauseigenen Tiefgarage zur Verfügung.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 524, 1266, 'https://www.buerohamburg.de/objects/pdf/BHI_25296.pdf', null, 'filemaker', '25296') on conflict (id) do nothing;
