insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-21415')::uuid, md5('building-theodorstrasse-42-90-22761')::uuid, '21415', 'schoene-lofts-in-hamburgs-westend-village-21415', 'Schöne Lofts in Hamburgs Westend Village', 'Das Westend Village befindet sich unmittelbar an der BAB 7 und ist ein außergewöhnlicher Ort zum Leben und Arbeiten.  Das ehemalige Fabrikgelände der British American Tobacco aus …', 'Das Westend Village befindet sich unmittelbar an der BAB 7 und ist ein außergewöhnlicher Ort zum Leben und Arbeiten.  Das ehemalige Fabrikgelände der British American Tobacco aus dem 19. Jahrhundert hat sich nach beendeter Restaurierung in eine Anlage verwandelt, die durch ihr einmaliges Ambiente besticht. Der traditionelle Bestand wir durch moderne Neubauten erweitert und verbindet alt und neu auf eine harmonische Weise. Zur Ausstattung dieser Fläche gehören hohe Decken, getrennte WC-Einheiten, schallhemmende Deckensegel, eine bereits verlegte EDV- Verkabelung sowie eine hochwertige Teeküche. PKW-Stellplätze können auf dem Areal angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['stellplaetze']::text[], 196, 4300, 'https://www.buerohamburg.de/objects/pdf/BHI_21415.pdf', null, 'filemaker', '21415') on conflict (id) do nothing;
