insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-17681')::uuid, md5('building-basedowstrasse-12-20537')::uuid, '17681', 'flexibel-gestaltbare-bueroflaeche-an-der-bille-17681', 'Flexibel gestaltbare Bürofläche an der Bille', 'Das ansprechende Bürogebäude befindet sich in ruhiger Lage der City-Süd zwischen den Elbbrücken und der Hamburger Innenstadt. Die Anbindung an den ÖPNV ist durch die nahegelegene …', 'Das ansprechende Bürogebäude befindet sich in ruhiger Lage der City-Süd zwischen den Elbbrücken und der Hamburger Innenstadt. Die Anbindung an den ÖPNV ist durch die nahegelegene S-Bahnstation Rothenburgsort gesichert. Die gut belichteten Büro- oder Lagerfläche ist über vier zusammenhängende Geschosse verteilt und über zwei Treppenhäuser bzw. zwei Personenaufzüge miteinander verbunden. Die aktuelle Ausstattung umfasst Linoleumbodenbelag, separate WC-Einheiten und eine kleine Pantry. Die weitere Ausstattung und Aufteilung erfolgt in Absprache mit dem zukünftigen Mieter. Pkw-Stellplätze können am Objekt angemietet werden. Diese Bilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 194, 1942, 'https://www.buerohamburg.de/objects/pdf/BHI_17681.pdf', null, 'filemaker', '17681') on conflict (id) do nothing;
