insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-13568')::uuid, md5('building-hohe-bleichen-19-20354')::uuid, '13568', 'aussergewoehnliches-buero-hinter-historischer-fassade-13568', 'Außergewöhnliches Büro hinter historischer Fassade', 'Der denkmalgeschützte Ludwigshof befindet sich in bester Hamburger Geschäftslage nur wenige Fußminuten von Gänsemarkt und Binnenalster entfernt. Zahlreiche gastronomische Angebote …', 'Der denkmalgeschützte Ludwigshof befindet sich in bester Hamburger Geschäftslage nur wenige Fußminuten von Gänsemarkt und Binnenalster entfernt. Zahlreiche gastronomische Angebote sowie alle Geschäfte des täglichen Bedarfs prägen das direkte Umfeld. Die nahe gelegenen U- und S-Bahnstationen Gänsemarkt und Jungfernstieg sichern eine hervorragende Anbindung an das öffentliche Verkehrsnetz. Über ein großzügiges Foyer mit historischem Treppenhaus und zwei Personenaufzügen erschließt man die moderne Bürofläche. Zur aktuellen Ausstattung zählen ein heller Empfangs- und Loungebereich, Teppichfußboden, eine Verkabelung in Bodentanks, hohe Decken, Glaselemente und teilweise Glastrennwände, zum Teil außen liegender elektrischer Sonnenschutz, getrennte WC-Einheiten und eine Pantry. PKW-Stellplätze können im gegenüberliegenden Parkhaus des Hanse-Viertels angemietet werden. Diese Innenbilder sind beispielhaft gewählt und stammen aus einer ähnlichen Fläche im Objekt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['barrierefrei']::text[], 440, 585, 'https://www.buerohamburg.de/objects/pdf/BHI_13568.pdf', null, 'filemaker', '13568') on conflict (id) do nothing;
