insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25050')::uuid, md5('building-gaensemarkt-43-20354')::uuid, '25050', 'premium-bueroflaeche-zwischen-gaensemarkt-und-stephansplatz-25050', 'Premium-Bürofläche zwischen Gänsemarkt und Stephansplatz', 'Das markante Eckgebäude befindet sich in erstklassiger Hamburger Innenstadtlage, in unmittelbarer Nähe zu den U-Bahn-Stationen Gänsemarkt und Stephansplatz. Diese gewährleisten …', 'Das markante Eckgebäude befindet sich in erstklassiger Hamburger Innenstadtlage, in unmittelbarer Nähe zu den U-Bahn-Stationen Gänsemarkt und Stephansplatz. Diese gewährleisten zusammen mit mehreren Buslinien eine hervorragende Anbindung an den öffentlichen Personennahverkehr. Das lebendige Umfeld ist geprägt von attraktiven Einkaufspassagen, zahlreichen Geschäften sowie hochwertigen Boutiquen aus unterschiedlichsten Branchen. Eine große Auswahl an Restaurants und Cafés ist in wenigen Gehminuten erreichbar und bietet vielfältige Möglichkeiten für die Mittagspause oder Geschäftstermine.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-25050-1')::uuid, md5('property-25050')::uuid, 'Mietfläche', 587, 25, null, 'filemaker', '25050-1') on conflict (id) do nothing;
