  (md5('image-25050-2')::uuid, md5('property-25050')::uuid, 'https://www.buerohamburg.de/objects/images/25050/02_webBig.jpg', 'Premium-Bürofläche zwischen Gänsemarkt und Stephansplatz – Bild 2', 1, 'filemaker', '25050-02'),
