insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25314')::uuid, md5('building-alter-wall-12-20457')::uuid, '25314', 'repraesentative-bueroflaeche-in-historischem-gebaeude-am-alten-wall-25314', 'Repräsentative Bürofläche in historischem Gebäude am Alten Wall', 'Das denkmalgeschützte Gebäude am Alten Wall wurde 2017 umfassend modernisiert und verbindet historische Architektur mit modernsten Bürostandards. Die ursprünglichen Gemäuer der …', 'Das denkmalgeschützte Gebäude am Alten Wall wurde 2017 umfassend modernisiert und verbindet historische Architektur mit modernsten Bürostandards. Die ursprünglichen Gemäuer der ehemaligen Stadtmauer verleihen der Immobilie einen einzigartigen Charakter, während die Sanierung unter besonderer Berücksichtigung von Energie- und Umweltaspekten nachhaltig und hocheffizient umgesetzt wurde.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-25314-1')::uuid, md5('property-25314')::uuid, 'Mietfläche', 591, 39, null, 'filemaker', '25314-1') on conflict (id) do nothing;
