insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-21879')::uuid, md5('building-eidelstedter-platz-21-22523')::uuid, '21879', 'moderner-neubau-im-herzen-von-eidelstedt-21879', 'Moderner Neubau im Herzen von Eidelstedt', 'Das ansprechende Neubauprojekt befindet sich in zentraler Stadtteillage direkt am Eidelstedter Marktplatz. Der Anschluss an die A7 und A23 ist ebenso schnell erreicht wie der nahe …', 'Das ansprechende Neubauprojekt befindet sich in zentraler Stadtteillage direkt am Eidelstedter Marktplatz. Der Anschluss an die A7 und A23 ist ebenso schnell erreicht wie der nahe gelegenen zentrale Omnibusbahnhof. Desweiteren sichert die S-Bahn-Station Elbgaustraße eine sehr gute Anbindung an das öffentliche Verkehrsnetz.  Vielseitige Einkaufsmöglichkeiten im Eidelstedt Center und diverse Cafés und Restaurants beleben das direkte Umfeld. Die hochwertige Ausstattung der Bürofläche umfasst Glasfaseranschluss, Hohlraumboden und außenliegenden Sonnenschutz. Die Aufteilung erfolgt individuell in Absprache mit dem zukünftigen Mieter. KFZ- Stellplätze können in der Quartierstiefgarage der Eidelstedter Höfe angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 272, 594, 'https://www.buerohamburg.de/objects/pdf/BHI_21879.pdf', null, 'filemaker', '21879') on conflict (id) do nothing;
