insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24996')::uuid, md5('building-raboisen-5-20095')::uuid, '24996', 'repraesentative-bueroflaeche-in-einem-der-aeltesten-kontohaeuser-hamburgs-24996', 'Repräsentative Bürofläche in einem der ältesten Kontohäuser Hamburgs', 'Das Brügge Haus, erbaut 1904, ist eines der ältesten Kontorhäuser in Hamburg und besticht noch heute durch seine Jugendstil- und Art Deco-Elemente. Die historische Fassade wurde …', 'Das Brügge Haus, erbaut 1904, ist eines der ältesten Kontorhäuser in Hamburg und besticht noch heute durch seine Jugendstil- und Art Deco-Elemente. Die historische Fassade wurde erhalten, die Bestandsstockwerke komplett entkernt, modernisiert und auf den neusten Stand der Technik gebracht. Über den repräsentativen Eingangsbereich mit zwei Personenaufzügen sind die jeweiligen Etagen zu erreichen. Zur aktuellen Ausstattung zählen u.a. Amticobodenbelag im Flur, Teppichboden in den Büroräumen, Kühldecken, Hohlraumboden, eine Pantry sowie moderne WC-Einheiten. Die weitere Ausstattung und Aufteilung erfolgt in Absprache mit dem zukünftigen Mieter. Alle Bürogeschosse verfügen über zum Innenhof liegende Balkone. Diese Innenbilder sind beispielhaft gewählt. PKW-Stellplätze können im Umfeld angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse']::text[], 265, 596, 'https://www.buerohamburg.de/objects/pdf/BHI_24996.pdf', null, 'filemaker', '24996') on conflict (id) do nothing;
