insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25134')::uuid, md5('building-hans-henny-jahnn-weg-49-53-22085')::uuid, '25134', 'uhlenhorst-individuelle-bueroflaeche-direkt-am-osterbekkanal-25134', 'Uhlenhorst: Individuelle Bürofläche direkt am Osterbekkanal', 'Der Osterbekhof befindet sich im urbanen Stadtteil Uhlenhorst direkt am Osterbekkanal. Die Anbindung an das öffentliche Verkehrsnetz ist durch diverse Buslinien gesichert. …', 'Der Osterbekhof befindet sich im urbanen Stadtteil Uhlenhorst direkt am Osterbekkanal. Die Anbindung an das öffentliche Verkehrsnetz ist durch diverse Buslinien gesichert. Vielseitge Einkaufsmöglichkeiten und zahlreiche Cafés und Restaurants im nahe gelegenen Mühlenkamp und Hofweg sind fußläufig schnell erreicht. Ein begrünter, überdachter Innenhof schafft eine freundliche Atmosphäre. Die helle Bürofläche erschließt sich über einen repräsentativen Eingangsbereich mit Personenaufzügen. Die aktuelle Ausstattung umfasst Fensterbrüstungskanäle und außen liegenden Sonnenschutz. Die Aufteilung und weitere Ausbauwünsche erfolgen in Absprache mit dem zukünftigen Mieter. PKW-Stellplätze können in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze', 'wasserblick']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_25134.pdf', null, 'filemaker', '25134') on conflict (id) do nothing;
