insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24799')::uuid, md5('building-an-der-alster-3-5-20099')::uuid, '24799', 'st-georg-bueroflaeche-in-top-lage-24799', 'St.Georg: Bürofläche in Top-Lage', 'Der von den Architekten Bothe, Richter und Teherani entwickelte, außergewöhnliche Bürokomplex befindet sich In exponierter Lage direkt an der Hamburger Außenalster in St. Georg. …', 'Der von den Architekten Bothe, Richter und Teherani entwickelte, außergewöhnliche Bürokomplex befindet sich In exponierter Lage direkt an der Hamburger Außenalster in St. Georg. Diverse Buslinien und die U-Bahnhaltestelle Lohmühlenstraße sichern eine gute Anbindung an das öffentliche Verkehrsnetz. Die Lange Reihe mit vielseitigen Einkaufsmöglichkeiten und zahlreichen Cafés und Restaurants ist fußläufig schnell erreicht und erhöht die Attraktivität dieser beliebten Stadtteillage. Die effizient aufgeteilte Bürofläche befindet sich im 2. Obergeschoss und erschließt sich über ein modernes Treppenhaus mit zwei Personenaufzügen. Die aktuellen Ausstattung umfasst unter anderem einen PVC-Bodenbelag in Holzoptik in den Flurbereichen, Glaswände, Teppichboden, außenliegenden, elektrischen Sonnenschutz, ein Beleuchtungskonzept, Bodentanks, eine Pantry und separate WC-Einheiten. Diese Innenbilder sind beispielhaft gewählt und stammen aus einer ähnlichen Fläche im Objekt. PKW-Stellplätze können in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 183, 606, 'https://www.buerohamburg.de/objects/pdf/BHI_24799.pdf', null, 'filemaker', '24799') on conflict (id) do nothing;
