insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-4057')::uuid, md5('building-suederstrasse-282-20537')::uuid, '4057', 'hanseatische-atmosphaere-im-stoertebeker-haus-mit-balkon-4057', 'Hanseatische Atmosphäre im Störtebeker Haus mit Balkon', 'Das Büro- und Geschäftshaus befindet sich in zentraler City-Süd-Lage an den Hauptverkehrsachsen Heidenkampsweg und Amsinckstraße. Die Autobahnen 1, 7 und 24 sind in wenigen …', 'Das Büro- und Geschäftshaus befindet sich in zentraler City-Süd-Lage an den Hauptverkehrsachsen Heidenkampsweg und Amsinckstraße. Die Autobahnen 1, 7 und 24 sind in wenigen Minuten mit dem Pkw erreicht. Das 7- geschossige Störtebeker Haus nimmt mit der besonderen Fassadengestaltung bewusst Bezug zu den traditionellen, hanseatischen Kontorhäusern. Die Büroflächen werden bezugsfertig ausgebaut. Ein ca. 62 qm großer Balkon fließt zzgl. anteilig mit in die Bürofläche ein. Der Ausbaustandard entspricht modernsten Anforderungen. Der Mietpreis variiert je nach Ausstattung und Lage im Objekt ab 13,90 Euro pro qm. PKW-Stellplätze können nach Rücksprache angemietet werden. Die Innenbilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse', 'barrierefrei', 'stellplaetze']::text[], 160, 682, 'https://www.buerohamburg.de/objects/pdf/BHI_4057.pdf', null, 'filemaker', '4057') on conflict (id) do nothing;
