insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-17494')::uuid, md5('building-brandstwiete-1-20457')::uuid, '17494', 'moderne-bueroflaechen-in-bester-city-lage-17494', 'Moderne Büroflächen in bester City-Lage', 'Das moderne Büro- und Geschäftsgebäude befindet sich in markanter Ecklage zwischen Binnenalster und Speicherstadt. Die nahe gelegenen U- und S-Bahnstationen Jungfernstieg und …', 'Das moderne Büro- und Geschäftsgebäude befindet sich in markanter Ecklage zwischen Binnenalster und Speicherstadt. Die nahe gelegenen U- und S-Bahnstationen Jungfernstieg und Meßberg sorgen für eine sehr gute Anbindung an das öffentliche Verkehrsnetz. Vielseitige Einkaufsmöglichkeiten und diverse Cafés und Restaurants prägen das direkte Umfeld. insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-17494-1')::uuid, md5('property-17494')::uuid, 'Mietfläche', 620, 26, null, 'filemaker', '17494-1') on conflict (id) do nothing;
