insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23454')::uuid, md5('building-auf-dem-koenigslande-37-39-22041')::uuid, '23454', 'wandsbek-moderne-bueroflaeche-in-ruhiger-lage-23454', 'Wandsbek: Moderne Bürofläche in ruhiger Lage', 'Das moderne, lichtdurchflutete Bürogebäude befindet sich in ruhiger Lage nahe der Walddörferstraße. Vielseitige Einkaufsmöglichkeiten im Wandsbeker Quarree und diverse Restaurants …', 'Das moderne, lichtdurchflutete Bürogebäude befindet sich in ruhiger Lage nahe der Walddörferstraße. Vielseitige Einkaufsmöglichkeiten im Wandsbeker Quarree und diverse Restaurants und Cafés prägen das direkte Umfeld  und sind fußläufig schnell erreicht. Der Anschluss an das öffentliche Verkehrsnetz ist durch diverse Buslinien und die U-Bahn-Station Wandsbek Markt gesichert. Der nahe gelegene Horner Kreisel gewährleistet eine gute Anbindung an die Autobahnen A1 und A24.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-23454-1')::uuid, md5('property-23454')::uuid, 'Mietfläche', 622, 14, null, 'filemaker', '23454-1') on conflict (id) do nothing;
