insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25156')::uuid, md5('building-baumwall-3-20459')::uuid, '25156', 'beeindruckende-deckenhoehe-loftige-bueroflaeche-am-baumwall-25156', 'Beeindruckende Deckenhöhe: Loftige Bürofläche am Baumwall', 'Das Slomanhaus befindet sich in markanter Ecklage direkt am Hamburger Hafen mit einem schönen Ausblick auf Elbe und Speicherstadt. Die nahe gelegenen U-Bahn-Stationen Baumwall und …', 'Das Slomanhaus befindet sich in markanter Ecklage direkt am Hamburger Hafen mit einem schönen Ausblick auf Elbe und Speicherstadt. Die nahe gelegenen U-Bahn-Stationen Baumwall und Meßberg sichern eine sehr gute Anbindung an den öffentlichen Nahverkehr. Auch die Autobahnen A1 und A7 sind schnell erreicht. Im direkten Umfeld befinden sich diverse Cafés und Restaurants für abwechslungsreiche Mittagspausen. Die Innenstadt mit allen Einkaufsmöglichkeiten ist fußläufig gut erreichbar. Die historische Außenfassade und die großzügigen Treppenhäuser des denkmalgeschützten Gebäudes wurden in der Vergangenheit umfangreich restauriert. Die Aufteilung und Ausstattung der kompakten Fläche erfolgt in Absprache mit dem zukünftigen Mieter. PKW-Stellplätze stehen in der Umgebung zur Anmietung bereit. Die Innenansichten stammen aus einer ähnlichen Fläche im Gebäude.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['erdgeschoss']::text[], 137, 956, 'https://www.buerohamburg.de/objects/pdf/BHI_25156.pdf', null, 'filemaker', '25156') on conflict (id) do nothing;
