insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23051')::uuid, md5('building-grosse-elbstrasse-59-63-22767')::uuid, '23051', 'holzhafen-hamburg-hochwertige-bueroflaeche-mit-elbblick-und-terrasse-23051', 'Holzhafen Hamburg - hochwertige Bürofläche mit Elbblick und Terrasse', 'Der imposante Bürokomplex befindet sich in prominenter Uferlage mit einem herrlichen Blick über die Elbe und den Hamburger Hafen. Das Gebäude erschließt sich über eine …', 'Der imposante Bürokomplex befindet sich in prominenter Uferlage mit einem herrlichen Blick über die Elbe und den Hamburger Hafen. Das Gebäude erschließt sich über eine repräsentative und lichtdurchflutete Eingangshalle. Die hochwertige Ausstattung der modernen Bürofläche umfasst teilweise Glastrennwände, thermische Bauteilaktivierung mit Lüftungsfunktion, Sonnenschutzverglasung, innenliegenden Blendschutz, Bodentanks, eine voll eingerichtete Pantry und separate WC-Einheiten. Die weitere Ausstattung und Aufteilung erfolgt in Absprache mit dem zukünftigen Mieter. Highlight ist eine ca. 54 qm große Terrasse, welche hälftig zum obigen Mietzins in die Gesamtmiete mit einfließt. Die Innenansichten stammen aus einer ähnlichen Mieteinheit im Objekt. PKW-Stellplätze können in der hauseigenen und flutgeschützten Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse', 'stellplaetze']::text[], 531, 648, 'https://www.buerohamburg.de/objects/pdf/BHI_23051.pdf', null, 'filemaker', '23051') on conflict (id) do nothing;
